    [Fact]
    public void Deposit_avoiding_jammed_cassette_succeeds()
    {
        var (result, dispenser) = Run(0, 200, N(0, 0, 0), Denomination.Twenty, new Operation.Deposit(N(1, 0, 1)));

        Assert.Equal(AtmStatus.Ok, result.Status);
