import sys
def tdiv(x,y):
    q=abs(x)//abs(y)
    return q if (x>=0)==(y>0) else -q
def fewest_cap(a,av):
    return fewest(a,*av)
R={
 'b': lambda b,w,a,fee: b,
 'b-fee': lambda b,w,a,fee: b-fee,
 '200-w': lambda b,w,a,fee: 200-w,
 'b-a-fee': lambda b,w,a,fee: b-a-fee,
 '200-w-a': lambda b,w,a,fee: 200-w-a,
 'b-w': lambda b,w,a,fee: b-w,
 'min': lambda b,w,a,fee: min(b-fee,200-w),
 'b-a': lambda b,w,a,fee: b-a,
 'w': lambda b,w,a,fee: w,
 '200-w-fee': lambda b,w,a,fee: 200-w-fee,
}
def bug(v, r, dens):
    b,w,F,T,C,j,a=v
    if a<=0 or a%10: return ('IA',None)
    if w+a>200: return ('DL',None)
    fee=5 if a>100 else 0
    if a+fee>b: return ('IF',None)
    av=list(avail(F,T,C,j))
    x=R[r](b,w,a,fee)
    for i,d in enumerate((50,20,10)):
        if d in dens: av[i]=max(0,min(av[i], tdiv(x,d)))
    c=fewest(a,*av)
    return ('CD',None) if c is None else ('OK',c)
import itertools
visl=[v for v in vis if len(v)==7]
def dom():
    for b in range(0,251,5):
      for w in range(0,201,10):
        for a in range(10,201,10):
          if w+a>200: continue
          fee=5 if a>100 else 0
          if a+fee>b: continue
          for F in range(6):
            for T in range(6):
              for C in range(6):
                for j in (0,50,20,10): yield (b,w,F,T,C,j,a)
dl=list(dom())
res=[]
for r in R:
  for k in range(1,4):
    for dens in itertools.combinations((50,20,10),k):
      vd=sum(1 for v in visl if bug(v,r,dens)!=spec(*v))
      dd=sum(1 for v in dl if bug(v,r,dens)!=spec(*v)) if vd<50 else -1
      print(r,dens,vd,dd,flush=True)
