using Atm;
static NoteCounts N(int f, int t, int c) => new(f, t, c);
static NoteCounts? Fewest(int amount, NoteCounts av)
{
    NoteCounts? best = null;
    for (var f = 0; f <= av.Fifties; f++)
    for (var t = 0; t <= av.Twenties; t++)
    for (var c = 0; c <= av.Tens; c++)
    {
        var cand = N(f, t, c);
        if (cand.Value == amount && (best is null || cand.Total < best.Value.Total)) best = cand;
    }
    return best;
}
Denomination?[] jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
int[] amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
long diffs = 0, total = 0;
var examples = new List<string>();
var fewestCache = new Dictionary<(int, NoteCounts), NoteCounts?>();
for (var f = 0; f <= 5; f++)
for (var t = 0; t <= 5; t++)
for (var c = 0; c <= 5; c++)
foreach (var j in jams)
{
    var stock = N(f, t, c);
    var av = N(j == Denomination.Fifty ? 0 : f, j == Denomination.Twenty ? 0 : t, j == Denomination.Ten ? 0 : c);
    var fw = amounts.ToDictionary(a => a, a => a > 0 ? Fewest(a, av) : null);
    for (var b = 0; b <= 250; b += 5)
    for (var w = 0; w <= 200; w += 10)
    {
        var acc = new AccountState(b, w);
        foreach (var a in amounts)
        {
            AtmResult exp; NoteCounts expStock = stock;
            var fee = a > 100 ? 5 : 0;
            if (a <= 0 || a % 10 != 0) exp = new(AtmStatus.InvalidAmount, default, 0, acc);
            else if (w + a > 200) exp = new(AtmStatus.DailyLimitExceeded, default, 0, acc);
            else if (a + fee > b) exp = new(AtmStatus.InsufficientFunds, default, 0, acc);
            else if (fw[a] is not { } n) exp = new(AtmStatus.CannotDispense, default, 0, acc);
            else { exp = new(AtmStatus.Ok, n, fee, new AccountState(b - a - fee, w + a)); expStock = stock - n; }
            var d = new MoneyDispenser(stock, j);
            AtmResult got;
            try { got = new CashMachine(d).Execute(acc, new Operation.Withdraw(a)); }
            catch (Exception e) { got = new((AtmStatus)99, default, 0, acc); }
            total++;
            if (got != exp || d.Stock != expStock)
            {
                diffs++;
                if (examples.Count < 10) examples.Add($"W b={b} w={w} stock={stock} jam={j} a={a} exp={exp} got={got}");
            }
        }
        for (var m = 1; m < 8 + 0; m++) { }
        for (var m = 0; m < 8; m++)
        {
            var dep = N(m & 1, (m >> 1) & 1, (m >> 2) & 1);
            AtmResult exp; NoteCounts expStock = stock;
            var after = stock + dep;
            if (dep.Total == 0) exp = new(AtmStatus.InvalidAmount, default, 0, acc);
            else if (j is { } jj && dep.Of(jj) > 0) exp = new(AtmStatus.CassetteJammed, default, 0, acc);
            else if (after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5) exp = new(AtmStatus.CassetteFull, default, 0, acc);
            else { exp = new(AtmStatus.Ok, default, 0, acc with { Balance = b + dep.Value }); expStock = after; }
            var d = new MoneyDispenser(stock, j);
            AtmResult got;
            try { got = new CashMachine(d).Execute(acc, new Operation.Deposit(dep)); }
            catch (Exception) { got = new((AtmStatus)99, default, 0, acc); }
            total++;
            if (got != exp || d.Stock != expStock)
            {
                diffs++;
                if (examples.Count < 10) examples.Add($"D b={b} w={w} stock={stock} jam={j} dep={dep} exp={exp} got={got}");
            }
        }
    }
}
Console.WriteLine($"DIFFS {diffs} / {total}");
foreach (var e in examples) Console.WriteLine(e);
