// states: b w F T C j a
var lines = File.ReadAllLines("/tmp/visited_u.txt");
var vis = new List<int[]>();
foreach (var l in lines) { var p = l.Split(' '); if (p.Length == 7) vis.Add(p.Select(int.Parse).ToArray()); }
// restrict to states reaching check 4
var v4 = vis.Where(s => s[6] > 0 && s[6] % 10 == 0 && s[1] + s[6] <= 200 && s[6] + (s[6] > 100 ? 5 : 0) <= s[0]).ToArray();
Console.WriteLine($"visited {vis.Count}, reaching check4 {v4.Length}");
var dom = new List<int[]>();
for (int b = 0; b <= 250; b += 5) for (int w = 0; w <= 200; w += 10) for (int a = 10; a <= 200; a += 10)
{
    if (w + a > 200 || a + (a > 100 ? 5 : 0) > b) continue;
    for (int F = 0; F <= 5; F++) for (int T = 0; T <= 5; T++) for (int C = 0; C <= 5; C++) foreach (var j in new[] { 0, 50, 20, 10 })
        dom.Add(new[] { b, w, F, T, C, j, a });
}
Console.WriteLine($"domain check4 {dom.Count}");
// fewest table
int[,,,] few = new int[21, 6, 6, 6];
for (int a = 10; a <= 200; a += 10) for (int F = 0; F < 6; F++) for (int T = 0; T < 6; T++) for (int C = 0; C < 6; C++)
{
    int best = -1, bt = 99;
    for (int f = 0; f <= F; f++) for (int t = 0; t <= T; t++) { int r = a - 50 * f - 20 * t; if (r < 0 || r % 10 != 0 || r / 10 > C) continue; int c = r / 10; if (f + t + c < bt) { bt = f + t + c; best = f * 100 + t * 10 + c; } }
    few[a / 10, F, T, C] = best;
}
int Spec(int[] s) { int F = s[5] == 50 ? 0 : s[2], T = s[5] == 20 ? 0 : s[3], C = s[5] == 10 ? 0 : s[4]; return few[s[6] / 10, F, T, C]; }
string[] tn = { "b", "w", "a", "fee", "200", "100", "5" };
int Term(int[] s, int i) => i switch { 0 => s[0], 1 => s[1], 2 => s[6], 3 => s[6] > 100 ? 5 : 0, 4 => 200, 5 => 100, _ => 5 };
int Cap(int[] s, int[] coef, int mask)
{
    int R = 0; for (int i = 0; i < 7; i++) if (coef[i] != 0) R += coef[i] * Term(s, i);
    int F = s[5] == 50 ? 0 : s[2], T = s[5] == 20 ? 0 : s[3], C = s[5] == 10 ? 0 : s[4];
    if ((mask & 1) != 0) F = Math.Max(0, Math.Min(F, R / 50));
    if ((mask & 2) != 0) T = Math.Max(0, Math.Min(T, R / 20));
    if ((mask & 4) != 0) C = Math.Max(0, Math.Min(C, R / 10));
    return few[s[6] / 10, F, T, C];
}
var specV = v4.Select(Spec).ToArray();
var specD = dom.Select(Spec).ToArray();
var coef = new int[7];
int total = 1; for (int i = 0; i < 7; i++) total *= 3;
var results = new List<(long, string)>();
for (int code = 0; code < total; code++)
{
    int x = code; bool any = false;
    for (int i = 0; i < 7; i++) { coef[i] = x % 3 - 1; x /= 3; any |= coef[i] != 0; }
    if (!any) continue;
    for (int mask = 1; mask < 8; mask++)
    {
        bool bad = false;
        for (int k = 0; k < v4.Length; k++) if (Cap(v4[k], coef, mask) != specV[k]) { bad = true; break; }
        if (bad) continue;
        long d = 0; for (int k = 0; k < dom.Count; k++) if (Cap(dom[k], coef, mask) != specD[k]) d++;
        if (d > 0)
        {
            var name = string.Join("", Enumerable.Range(0, 7).Where(i => coef[i] != 0).Select(i => (coef[i] > 0 ? "+" : "-") + tn[i])) + " mask" + mask;
            results.Add((d, name));
            Console.WriteLine($"SURVIVOR {name} domdiff={d}");
        }
    }
}
