var v4 = vis.Where(s => s[6] > 0 && s[6] % 10 == 0 && s[1] + s[6] <= 200 && s[6] + (s[6] > 100 ? 5 : 0) <= s[0]).ToArray();
var dom = new List<int[]>();
for (int b = 0; b <= 250; b += 5) for (int w = 0; w <= 200; w += 10) for (int a = 10; a <= 200; a += 10)
{
    if (w + a > 200 || a + (a > 100 ? 5 : 0) > b) continue;
    for (int F = 0; F <= 5; F++) for (int T = 0; T <= 5; T++) for (int C = 0; C <= 5; C++) foreach (var j in new[] { 0, 50, 20, 10 })
        dom.Add(new[] { b, w, F, T, C, j, a });
}
string[] tn = { "b", "w", "a", "fee", "200", "100", "5" };
int Term(int[] s, int i) => i switch { 0 => s[0], 1 => s[1], 2 => s[6], 3 => s[6] > 100 ? 5 : 0, 4 => 200, 5 => 100, _ => 5 };
int Lin(int[] s, int[] co) { int R = 0; for (int i = 0; i < 7; i++) if (co[i] != 0) R += co[i] * Term(s, i); return R; }
// returns encoded result: status*1e6 + notes (f,t,c offset) ; plus stock
long Sim(int[] s, int[] c1, int[] c2)
{
    int a = s[6], j = s[5];
    int AF = j == 50 ? 0 : s[2], AT = j == 20 ? 0 : s[3], AC = j == 10 ? 0 : s[4];
    int R1 = c1 == null ? a : Lin(s, c1);
    int R2 = c2 == null ? a : Lin(s, c2);
    bool found = false; int bf = 0, bt = 0, bc = 0;
    for (int f = Math.Min(AF, R1 / 50); f >= 0; f--)
    {
        int after = a - f * 50;
        int x = R2 - f * 50;
        for (int t = Math.Min(AT, x / 20); t >= 0; t--)
        {
            int rest = after - t * 20;
            if (rest % 10 != 0 || rest / 10 > AC) continue;
            int c = rest / 10;
            if (!found || f + t + c < bf + bt + bc) { found = true; bf = f; bt = t; bc = c; }
        }
    }
    if (!found) return 1;
    int sf = s[2], st = s[3], sc = s[4];
    int rf = bf, rt = bt, rc = bc; int df = 0, dt = 0, dc = 0; int it = 0;
    while (rf + rt + rc > 0)
    {
        if (++it > 20) return 3;
        int room = 4; int pf = Math.Min(room, rf); room -= pf; int pt = Math.Min(room, rt); room -= pt; int pc = Math.Min(room, rc);
        rf -= pf; rt -= pt; rc -= pc;
